describe('Popover Toggle Functionality', () => {
  beforeEach(() => {
    cy.visit('/popover-page');
  });

  it('should toggle popover on button click', () => {
    // Verify popover is initially closed
    cy.get('[data-testid="popover-content"]').should('not.be.visible');
    cy.get('[data-testid="popover-button"]').should('be.visible');

    // Click the popover button to open it
    cy.get('[data-testid="popover-button"]').click();

    // Verify popover is now visible
    cy.get('[data-testid="popover-content"]').should('be.visible');
    cy.get('[data-testid="popover-title"]').should('contain', 'Popover Content');

    // Click the popover button again to close it
    cy.get('[data-testid="popover-button"]').click();

    // Verify popover is now closed
    cy.get('[data-testid="popover-content"]').should('not.be.visible');
  });

  it('should close popover when clicking outside', () => {
    // Open the popover
    cy.get('[data-testid="popover-button"]').click();
    cy.get('[data-testid="popover-content"]').should('be.visible');

    // Click outside the popover area
    cy.get('[data-testid="popover-button"]').click();

    // Verify popover is closed
    cy.get('[data-testid="popover-content"]').should('not.be.visible');

    // Open popover again
    cy.get('[data-testid="popover-button"]').click();
    cy.get('[data-testid="popover-content"]').should('be.visible');

    // Click outside again to close
    cy.get('[data-testid="popover-button"]').click();
    cy.get('[data-testid="popover-content"]').should('not.be.visible');
  });
});
